-- Fiche médicale (document type FM): the vaccination dates and the signature date become date blanks (date
-- picker when filled online, JJ/MM/AAAA in the PDF), and the allergy / medical blanks are linked to the member's
-- Médical tab (data-save), so a fiche signed online updates Allergies and Remarques médicales.
-- Matched by the label written before each blank (tolerant to the editor's wrapper <span>s); a template edited
-- differently just keeps the blanks it can't match. Runs once (DataPatchRunner).
UPDATE document_types SET template_html = regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(template_html, '(Anti diphtérique, tétanos et polio\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-date="1" data-save="medicalNotes" \2'), '(Anti hépatite A\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-date="1" data-save="medicalNotes" \2'), '(Anti typhoïdique Vi\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-date="1" data-save="medicalNotes" \2'), '(Anti ROR \(rougeole, oreillons, rubéole\)\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-date="1" data-save="medicalNotes" \2'), '(Aliments \(lactose, gluten…\)\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="allergies" \2'), '(Médicaments\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="allergies" \2'), '(Autre\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="allergies" \2'), '(du traitement en cas de crise\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="medicalNotes" \2'), '(du régime alimentaire spécifique\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="medicalNotes" \2'), '(du médecin de famille\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="medicalNotes" \2'), '(de la personne à contacter en cas d''urgence\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-save="medicalNotes" \2'), '((?:;|\s)Date\s*:\s*(?:&nbsp;|\s)*(?:</[a-z0-9]+>\s*)*(?:<span[^>]*>\s*)*<span )(data-w=)', '\1data-date="1" \2'), '(Antécédents médicaux et chirurgicaux\s*(?:</[a-z0-9]+>\s*)*<div )(data-h=)', '\1data-save="medicalNotes" \2'), '(Maladie chronique ou traitement à long terme actuellement suivi\s*(?:</[a-z0-9]+>\s*)*<div )(data-h=)', '\1data-save="medicalNotes" \2')
WHERE code = 'FM' AND template_html IS NOT NULL AND template_html NOT LIKE '%data-save=%';
